/* @lc app=leetcode id=3453 lang=kotlin */ class Solution { fun separateSquares(squares: Array<IntArray>): Double = squares.sumOf { it[2].toLong() * it[2] }.let { T -> squares.flatMap { listOf(it[1].toLong() to it[2].toLong(), it[1].toLong() + it[2] to -it[2].toLong()) }.groupBy({ it.first }, { it.second }).toSortedMap().entries.fold(Triple(0L, 0L, 0L) to -1.0) { (st, ans), (y, ds) -> if (ans >= 0) st to ans else (st.third + st.second * (y - st.first)).let { a2 -> if (2 * a2 >= T) st to st.first + (T / 2.0 - st.third) / st.second else Triple(y, st.second + ds.sum(), a2) to -1.0 } }.second } }